"""v2 tests: admin-session upload, auto-manifest, multi-version, bundle, revoke, throttle, .env. Run: python tests/test_store_v2.py"""
import io, json, os, sys, tempfile, zipfile, importlib
from pathlib import Path
server = Path(__file__).resolve().parents[1] / "server"; sys.path.insert(0, str(server))
tmp = tempfile.TemporaryDirectory(); os.environ["BIMDEPLOY_HOME"] = tmp.name
for k in ("ADMIN", "ENROLLMENT", "DEVICE"): os.environ.pop(f"BIMDEPLOY_{k}_TOKEN", None)
# .env generated by manage.py init is picked up by main.py
import manage, argparse
manage.ENV = Path(tmp.name) / ".env.test"; assert manage.cmd_init(None) == 0
for line in manage.ENV.read_text().splitlines():
    if line.startswith("BIMDEPLOY_"): k, v = line.split("=", 1); os.environ[k] = v
assert len(os.environ["BIMDEPLOY_ADMIN_TOKEN"]) >= 48
from fastapi.testclient import TestClient
import main
c = TestClient(main.app)
assert not main.token_ok("replace-with-a-long-random-admin-secret", "replace-with-a-long-random-admin-secret"), "placeholder must be rejected"
tok = {"X-Admin-Token": os.environ["BIMDEPLOY_ADMIN_TOKEN"]}
assert c.post("/api/admin/bootstrap", headers=tok, json={"username": "boss", "password": "very-long-password-1", "role": "admin"}).status_code == 200
A = {"Authorization": "Bearer " + c.post("/api/auth/login", json={"username": "boss", "password": "very-long-password-1"}).json()["access_token"]}
# Simulate a normal server restart. A fresh module/app must use the same
# on-disk database: users are not bootstrap-only state.
assert (Path(tmp.name) / "data" / "deployment.db").is_file()
restarted = importlib.reload(main)
c = TestClient(restarted.app)
assert c.post("/api/auth/login", json={"username": "boss", "password": "very-long-password-1"}).status_code == 200

def pkg(ver, years=("2024", "2025")):
    m = {"id": "BIM.Tool", "version": ver, "packageType": "RevitAddin", "supportedRevitVersions": list(years), "displayName": "Tool"}
    b = io.BytesIO()
    with zipfile.ZipFile(b, "w") as z:
        z.writestr("manifest.json", json.dumps(m)); z.writestr("payload/T.addin", "<RevitAddIns/>"); z.writestr("payload/T.dll", "x" + ver)
    return b.getvalue()

ids = []
for v in ("1.0.0", "1.1.0"):  # admin SESSION only, no form fields: manifest read from ZIP
    r = c.post("/api/packages", headers=A, files={"file": ("p.zip", pkg(v), "application/zip")}, data={"release_notes": "n" + v}); assert r.status_code == 200, r.text; ids.append(r.json()["package_id"])
assert c.post("/api/packages", headers=A, files={"file": ("p.zip", pkg("1.1.0"), "application/zip")}).status_code == 409
assert c.post("/api/packages", files={"file": ("p.zip", pkg("9.9.9"), "application/zip")}).status_code == 401
assert c.post("/api/packages", headers=A, files={"file": ("p.zip", pkg("2.0.0", ("20x",)), "application/zip")}).status_code == 400
cat = c.get("/api/portal/catalog", headers=A).json()["packages"]
assert [p["version"] for p in cat] == ["1.1.0", "1.0.0"] and cat[0]["is_latest"] and not cat[1]["is_latest"]
b = c.get(f"/api/portal/packages/{ids[0]}/bundle", headers=A); assert b.status_code == 200
assert sorted(zipfile.ZipFile(io.BytesIO(b.content)).namelist()) == ["Install-BIMAddinPackage.ps1", "Install.bat", "package.zip"]
assert c.post("/api/admin/users", headers=A, json={"username": "mod1", "password": "modeller-pass-123", "role": "modeller"}).status_code == 200
M = {"Authorization": "Bearer " + c.post("/api/auth/login", json={"username": "mod1", "password": "modeller-pass-123"}).json()["access_token"]}
assert c.post("/api/packages", headers=M, files={"file": ("p.zip", pkg("3.0.0"), "application/zip")}).status_code == 401  # modeller cannot publish
assert c.get(f"/api/portal/packages/{ids[0]}/download", headers=M).status_code == 200  # old version still downloadable
assert c.post(f"/api/admin/packages/{ids[0]}/revoke", headers=M).status_code == 401
assert c.post(f"/api/admin/packages/{ids[0]}/revoke", headers=A).status_code == 200
assert c.get(f"/api/portal/packages/{ids[0]}/download", headers=M).status_code == 404  # revoked hidden
assert [p["version"] for p in c.get("/api/portal/catalog", headers=M).json()["packages"]] == ["1.1.0"]
for _ in range(5): c.post("/api/auth/login", json={"username": "mod1", "password": "wrong-wrong-wrong"})
assert c.post("/api/auth/login", json={"username": "mod1", "password": "modeller-pass-123"}).status_code == 429

# one-click helper flow (before throttle lockout would matter, uses admin session)
pid=[x["package_id"] for x in c.get("/api/portal/catalog",headers=A).json()["packages"]][0]
t=c.post(f"/api/portal/packages/{pid}/install-token",headers=A); assert t.status_code==200,t.text
d=c.get(f"/api/install/packages/{pid}/download",params={"token":t.json()["token"]}); assert d.status_code==200
import hashlib; assert d.headers["x-package-sha256"]==hashlib.sha256(d.content).hexdigest()
assert c.get(f"/api/install/packages/{pid}/download",params={"token":"x"*30}).status_code==401
assert c.post(f"/api/portal/packages/{pid}/install-token").status_code==401
sb=c.get("/api/portal/setup-bundle",headers=A); assert sb.status_code==200
zz=zipfile.ZipFile(io.BytesIO(sb.content)); assert {"config.json","Setup.bat","BIMStore-Handler.ps1","Register-BIMStoreProtocol.ps1","Install-BIMAddinPackage.ps1"}<=set(zz.namelist())
print("PASS one-click: token mint, token download + sha header, bad token 401, setup bundle")
print("PASS v2: .env/init, admin persistence across restart, weak-secret rejection, admin-session upload, auto-manifest, multi-version, bundle, RBAC, revoke, login throttle")
